Code1: C program for Question 7(b).
```
/* main.c */
#include <stdio.h>
void main() {
  int i, j, k;
  float a[20];
  /* .......... */
  i = fone(a[5], a[15]);
  /* .......... */
  i = fone(a[5], a[15]);
  j = ftwo(i, k);
  printf("The results, i = %d, j = %d", i, j);
}
/* fone.c */
int fone(m1, m2) {
  int f1, ii, jj = 0;
  for (ii = 1; ii <= m2; ii++)
  {
    jj = ftwo(m1);
  }
  f1 = jj;
  return f1;
}
/* ftwo.c */
float ftwo(n) {
  float n1, n2;
  n2 = n / 2;
  if (n2 > 10)
    n1 = ftwo(n2);
  return n1;
}
```
